    {
      "name": "IsCoprime.wronskian_eq_zero_iff",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [NoZeroDivisors R] {a b : Polynomial R},\n  IsCoprime a b → (a.wronskian b = 0 ↔ Polynomial.derivative a = 0 ∧ Polynomial.derivative b = 0)"
    },
    {
      "name": "IsFractionRing.charZero",
      "module_name": "Mathlib.Algebra.CharP.Algebra",
      "kind": "instance",
      "type": "∀ (R : Type u_1) [inst : CommRing R] [IsDomain R] [CharZero R], CharZero (FractionRing R)"
    },
    {
      "name": "Polynomial.wronskian_zero_left",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a : Polynomial R), Polynomial.wronskian 0 a = 0"
    },
    {
      "name": "Polynomial.wronskian_self_eq_zero",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a : Polynomial R), a.wronskian a = 0"
    },
    {
      "name": "Polynomial.wronskian_zero_right",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a : Polynomial R), a.wronskian 0 = 0"
    },
    {
      "name": "divRadical_dvd_wronskian_right",
      "module_name": "Mathlib.RingTheory.Polynomial.Radical",
      "kind": "theorem",
      "type": "∀ {k : Type u_1} [inst : Field k] [inst_1 : DecidableEq k] (a b : Polynomial k),\n  EuclideanDomain.divRadical b ∣ a.wronskian b"
    },
    {
      "name": "divRadical_dvd_wronskian_left",
      "module_name": "Mathlib.RingTheory.Polynomial.Radical",
      "kind": "theorem",
      "type": "∀ {k : Type u_1} [inst : Field k] [inst_1 : DecidableEq k] (a b : Polynomial k),\n  EuclideanDomain.divRadical a ∣ a.wronskian b"
    },
    {
      "name": "Polynomial.separable_gcd_right",
      "module_name": "Mathlib.FieldTheory.Separable",
      "kind": "theorem",
      "type": "∀ {F : Type u_1} [inst : Field F] [inst_1 : DecidableEq (Polynomial F)] {g : Polynomial F} (f : Polynomial F),\n  g.Separable → (EuclideanDomain.gcd f g).Separable"
    }
